+	if err != nil && !errors.Is(err, os.ErrNotExist) {
+		return pinimpact.ModuleFiles{}, fmt.Errorf("read module sums: %w", err)
+	}
+	return pinimpact.ModuleFiles{GoMod: goMod, GoSum: goSum, Directory: directory}, nil
