+	}
+	if !bytes.Equal(before.GoMod, after.GoMod) || !bytes.Equal(before.GoSum, after.GoSum) {
+		return errors.New("gomad3 pin impact changed the candidate module's go.mod or go.sum")
+	}
+	return nil
